import AppKit

/// The leading icon a tab — in the strip, in the ⇧⌘J switcher and in the
/// File › Bookmarks menu — shows for the kind of file behind it (SPEC
/// Todo 15).
///
/// The name is all there is to go on: a tab's title is its file's last path
/// component, and the switcher is handed titles, not URLs. So the extension
/// decides, and a note with no file at all is asked for by its `nil` URL
/// rather than by a name it does not have.
///
/// Every kind draws this app's own art (`FileKindArt`, generated by
/// `Icon/make-file-icons.py` from `file-icon/`): a 96×64 rounded badge with
/// the extension lettered inside it, in `currentColor` so it loads as an
/// NSImage template and tints like an SF Symbol. The set has a drawing for
/// every extension it knows, an empty badge for a note with no name yet
/// (`untitled`) and a `?` badge for a kind nobody drew (`unknown`), so a
/// name never runs out of icon. The SF Symbol chain below is what is left of
/// the older scheme: nothing reaches it for a file name any more, and it
/// stays only so a caller naming a symbol directly still gets one.
///
/// Each stem is drawn twice — outlined normally, solid when the tab is
/// bookmarked. That is the whole bookmark mark: no second badge on the
/// corner, just the same icon filled in.
enum FileKindIcon {

    /// A note that has never been saved: no name, so no kind — an empty
    /// badge, which reads as "nothing yet" beside the lettered ones.
    static var untitledSymbolName: String { artPrefix + "untitled" }

    /// The badge a name the set has no drawing for gets: the same badge with
    /// a `?` in it.
    static var unknownSymbolName: String { artPrefix + "unknown" }

    /// The icon name for a note's file. `nil` — an untitled note — is the
    /// empty badge, which is the one case a name could never tell us about.
    /// A `"filetype-<stem>"` name is this app's own art, drawn by
    /// `image(named:pointSize:filled:)`; anything else is an SF Symbol name.
    static func symbolName(for url: URL?) -> String {
        guard let url else { return untitledSymbolName }
        return symbolName(forTitle: url.lastPathComponent)
    }

    /// The icon name for a file name, which is what a tab title is.
    static func symbolName(forTitle title: String) -> String {
        let ext = (title as NSString).pathExtension.lowercased()
        return artPrefix + artStem(forExtension: ext)
    }

    /// The image to actually draw for a name `symbolName(for:)` /
    /// `symbolName(forTitle:)` returned, at `pointSize`, outlined or —
    /// for a bookmarked tab — filled. A `"filetype-*"` name loads this app's
    /// own art as a template image, so it tints with `contentTintColor`
    /// exactly like an SF Symbol; anything else is asked of AppKit as an SF
    /// Symbol, same as every icon used to be drawn.
    static func image(named name: String, pointSize: CGFloat, filled: Bool = false) -> NSImage? {
        if name.hasPrefix(artPrefix) {
            return artImage(named: name, pointSize: pointSize, filled: filled)
        }
        return NSImage(systemSymbolName: name, accessibilityDescription: nil)?
            .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: pointSize, weight: .regular))
    }

    /// Whether a name `symbolName(forTitle:)` handed back is this app's own
    /// art rather than an SF Symbol. The two want different point sizes to
    /// stand the same height — a badge is a solid rectangle, a symbol a
    /// glyph — so a caller drawing both in one list has to be able to ask.
    static func isCustomArt(_ name: String) -> Bool { name.hasPrefix(artPrefix) }

    // MARK: - Custom art

    private static let artPrefix = "filetype-"

    /// Extension → the art set's file stem (its SVG's file name). Most
    /// extensions are their own stem; the cases below are the ones the set
    /// did not draw twice — a spelling folded onto the one that was drawn.
    /// A name with no extension at all reads as plain text; anything the set
    /// has never heard of gets the `?` badge.
    private static func artStem(forExtension ext: String) -> String {
        if ext.isEmpty { return "txt" }
        switch ext {
        case "mjs": return "js"
        case "latex", "ltx": return "tex"
        case "zsh", "bash", "fish": return "sh"
        case "text": return "txt"
        case "tif": return "tiff"
        case "heif": return "heic"
        case "mdown", "mkd": return "md"
        case "cc", "cxx": return "cpp"
        case "hh", "hxx": return "hpp"
        case "m", "mm": return "c"
        default:
            return FileKindArt.outline[ext] != nil ? ext : "unknown"
        }
    }

    /// One image per `(name, pointSize, filled)` asked for, built once.
    /// Rebuilding an `NSImage` from SVG text on every row draw would be
    /// wasteful.
    private static var artImageCache: [String: NSImage] = [:]

    /// The badge is 96×64 — three units wide to two high — and the lettering
    /// inside it wants to be read, so the height is what is chosen and the
    /// width follows at 1.5×. An SF Symbol at point size P draws about 1.2 P
    /// of ink; the badge is a solid rectangle rather than a glyph, so 1.35 P
    /// stands it the same height beside a title without towering over it:
    /// 15pt high in the strip's 16pt slot beside its 11pt title, 14 in the
    /// Bookmarks menu. The SVG is a vector rep, so any of these is crisp, 2×
    /// on Retina included. Measured off an offscreen render, not guessed.
    private static let artScale: CGFloat = 1.35
    private static let artAspect: CGFloat = 1.5

    private static func artImage(named name: String, pointSize: CGFloat, filled: Bool) -> NSImage? {
        let stem = String(name.dropFirst(artPrefix.count))
        let cacheKey = "\(name)@\(pointSize)\(filled ? "+filled" : "")"
        if let cached = artImageCache[cacheKey] { return cached }
        let table = filled ? FileKindArt.filled : FileKindArt.outline
        guard let svg = table[stem],
              let data = svg.data(using: .utf8),
              let image = NSImage(data: data)
        else { return nil }
        image.isTemplate = true
        let height = (pointSize * artScale).rounded()
        image.size = NSSize(width: (height * artAspect).rounded(), height: height)
        artImageCache[cacheKey] = image
        return image
    }
}
